def leaders_brute(a: list[int]) -> list[int]:
    out = []
    for i in range(len(a)):
        if all(a[i] > a[j] for j in range(i + 1, len(a))):
            out.append(a[i])
    return out

def leaders(a: list[int]) -> list[int]:
    out: list[int] = []
    mx = float("-inf")
    for x in reversed(a):
        if x > mx:
            out.append(x)
            mx = x
    out.reverse()
    return out
